import numpy as np, json, glob
O=json.load(open('/tmp/ecl/obsc.json'))
kp=json.load(open('/tmp/ecl/kp.json'))
KPD={}
for t,k in zip(kp['datetime'],kp['Kp']): KPD.setdefault(t[:10],[]).append(k)
DOME=['EBR','SPT','ESK','LER','HAD','NGK','GUI','CLF']; CAND=['MAB','DOU','WNG','SUA','BEL']; SUPP=['SFS']
PRIORITY=['EBR','SPT','HAD','CLF','NGK','ESK']  # dome Tier-1 priority table
Q=['2026-07-19','2026-07-20','2026-08-01','2026-08-06','2026-08-05']
EVD='2026-08-12'
def hm(s): h,m=map(int,s.split(':')); return h*60+m
def fmt(i): return '%02d:%02d'%divmod(int(i),60)
_cache={}
def load(s):
    if s in _cache: return _cache[s]
    d={}
    files=sorted(glob.glob(f'/tmp/ecl/day/{s}_*.txt')) or ([f'/tmp/ecl/{s}.txt'] if glob.glob(f'/tmp/ecl/{s}.txt') else []) 
    files+=sorted(glob.glob(f'/tmp/ecl2/ctl/{s}_*.txt'))
    for fn in files:
        comp=None
        for l in open(fn):
            if l.startswith('DATE'): comp=[c[-1] for c in l.split()[3:7]]; continue
            if not l.startswith('2026-'): continue
            p=l.split(); day=p[0]; i=int(p[1][:2])*60+int(p[1][3:5])
            v=[float(x) for x in p[3:7]]
            dd=d.setdefault(day,{k:np.full(1440,np.nan) for k in 'HXYZF'})
            if any(x>=88888 for x in v[:3]): continue
            if comp[0]=='H':
                dd['H'][i]=v[0]; dd['Z'][i]=v[2]
                D=np.radians(v[1]/60.0) # D in minutes of arc
                dd['X'][i]=v[0]*np.cos(D); dd['Y'][i]=v[0]*np.sin(D)
            else:
                dd['X'][i]=v[0]; dd['Y'][i]=v[1]; dd['Z'][i]=v[2]; dd['H'][i]=np.hypot(v[0],v[1])
            if v[3]<88888: dd['F'][i]=v[3]
    _cache[s]=d; return d
def base(d,comp,days,exclude=None):
    qd=[q for q in days if q in d and q!=exclude and np.isfinite(d[q][comp][15*60:21*60]).mean()>0.9]
    return np.nanmean(np.array([d[q][comp] for q in qd]),axis=0), qd
def contacts(s):
    o=O[s]; return hm(o['start_ut']),hm(o['t_max_ut']),hm(o['end_ut'])
def obsc_series(s):
    a=np.zeros(1440); o=O[s]; a[np.array(o['mins'])]=o['series']; return a

