import sys; sys.path.insert(0,'/tmp/ecl2')
from lib import *
G1,G4=hm('16:59'),hm('21:01')
def gauss(c,sig=10.0):
    t=np.arange(1440); return np.exp(-0.5*((t-c)/sig)**2)
def lag(x,tau):
    if tau<=0: return x.copy()
    y=np.zeros_like(x); a=1.0/tau
    for i in range(1,len(x)): y[i]=y[i-1]+a*(x[i]-y[i-1])
    return y
def pr(a,b):
    ok=np.isfinite(a)&np.isfinite(b)
    if ok.sum()<30: return np.nan
    return float(np.corrcoef(a[ok],b[ok])[0,1])
def detr(y,idx):
    ok=np.isfinite(y[idx]); 
    if ok.sum()<30: return y[idx]*np.nan
    p=np.polyfit(idx[ok],y[idx][ok],1); return y[idx]-np.polyval(p,idx)
def day_metrics(s,day,comp):
    d=load(s); b,qd=base(d,comp,Q,exclude=day)
    if day not in d: return None
    dev=d[day][comp]-b
    if np.isfinite(dev[14*60:22*60]).mean()<0.9: return None
    c1,tm,c4=contacts(s); ob=obsc_series(s)
    w=np.arange(tm-60,tm+61); seg=dev[w]; k=int(np.nanargmax(np.abs(seg)))
    kmin=int(np.nanargmin(seg))
    wl=np.arange(c1-60,c4+61); wg=np.arange(G1-60,G4+61)
    T={'obsc':-ob,'obsc_lag15':-lag(ob,15),'c14_local':-(gauss(c1)+gauss(c4)),'c14_global':-(gauss(G1)+gauss(G4))}
    r={}
    for name,t in T.items():
        ww=wg if name=='c14_global' else wl
        r[name]=pr(dev[ww],t[ww]); r[name+'_detr']=pr(detr(dev,ww),t[ww])
    # contact-phase amplitude: mean dev in +-10 min around local C1 and C4 relative to mean of [C1-60,C1-30]
    ref=np.nanmean(dev[c1-60:c1-30])
    a1=np.nanmin(dev[c1-10:c1+11])-ref; a4=np.nanmin(dev[c4-10:c4+11])-ref
    return dict(peak=float(seg[k]),t_peak=tm-60+k,min=float(seg[kmin]),t_min=tm-60+kmin,
                min_within30=abs(kmin-60)<=30, r=r, c1_dip=float(a1), c4_dip=float(a4), qd=qd)
if __name__=='__main__':
    days=sorted(load('EBR').keys())
    out={}
    for s in DOME+CAND+SUPP:
        out[s]={}
        for comp in 'HZ':
            out[s][comp]={}
            for day in days:
                m=day_metrics(s,day,comp)
                if m: out[s][comp][day]=m
    json.dump(out,open('tests.json','w'),default=lambda o: bool(o) if isinstance(o,np.bool_) else float(o))
    for comp in 'ZH':
        print('=== ',comp)
        for s in DOME+CAND+SUPP:
            e=out[s][comp].get(EVD)
            ctl=[v for k,v in out[s][comp].items() if k!=EVD]
            def frac(key,thr): 
                xs=[c['r'][key] for c in ctl if np.isfinite(c['r'][key])]; return f"{sum(x>thr for x in xs)}/{len(xs)}"
            rr=e['r']
            print(f"{s} peak {e['peak']:+6.2f}@{fmt(e['t_peak'])} min {e['min']:+6.2f}@{fmt(e['t_min'])} in30={e['min_within30']} "
                  f"r_obsc {rr['obsc']:+.2f}/{rr['obsc_detr']:+.2f} r_lag15 {rr['obsc_lag15_detr']:+.2f} r_c14L {rr['c14_local']:+.2f}/{rr['c14_local_detr']:+.2f} r_c14G {rr['c14_global']:+.2f}/{rr['c14_global_detr']:+.2f} "
                  f"C1dip {e['c1_dip']:+.1f} C4dip {e['c4_dip']:+.1f} | ctl r>0.7: obsc {frac('obsc_detr',0.7)} c14L {frac('c14_local_detr',0.7)} c14G {frac('c14_global_detr',0.7)}; r>0.5 c14L {frac('c14_local_detr',0.5)}")

