import sys; sys.path.insert(0,'/tmp/ecl2')
from lib import *
from tests import lag, gauss
G1,G4=hm('16:59'),hm('21:01')
def jfit(dev,idx,s):
    y=dev[idx]; ok=np.isfinite(y)
    if ok.mean()<0.9: return np.nan
    X=np.c_[np.ones(len(idx)),(idx-idx.mean())/60.0,s[idx]][ok]
    return float(np.linalg.lstsq(X,y[ok],rcond=None)[0][2])
res={}
if __name__!="__main__": raise SystemExit
for comp in ['Z','H']:
  for s in PRIORITY+['LER','SFS']:
    d=load(s); c1,tm,c4=contacts(s); ob=obsc_series(s)
    wl=np.arange(c1-60,c4+61); wg=np.arange(G1-60,G4+61)
    TPL={f'obsc_tau{t}':(lag(ob,t)/lag(ob,t).max(),wl) for t in [0,15,30,60]}
    TPL['c14_local']=(gauss(c1)+gauss(c4),wl); TPL['c14_global']=(gauss(G1)+gauss(G4),wg)
    for name,(tp,w) in TPL.items():
        ev=None; nul=[]; devs=[]
        for day in sorted(d):
            b,_=base(d,comp,Q,exclude=day); x=d[day][comp]-b
            a=jfit(x,w,tp)
            if not np.isfinite(a): continue
            if day==EVD: ev=a
            elif max(KPD[day][4:8])<=3.0: nul.append(a); devs.append(x)
        nul=np.array(nul); mu,sd=nul.mean(),nul.std(ddof=1)
        # detection power for a -17 nT (peak) injected signal: fraction of noise days where fitted A falls below mu-3sd
        pw=np.mean([jfit(x-17.0*tp,w,tp)<mu-3*sd for x in devs])
        res[f'{comp}|{s}|{name}']=dict(A=round(ev,2),null_mean=round(float(mu),2),null_sd=round(float(sd),2),z=round(float((ev-mu)/sd),2),n=len(nul),power_minus17_at_3sigma=round(float(pw),2),
            A_3sigma_detectable_nT=round(float(3*sd),1))
  print('==',comp)
  for s in PRIORITY+['LER','SFS']:
    print(s,' '.join(f"{n}:{res[f'{comp}|{s}|{n}']['A']:+.1f}(z{res[f'{comp}|{s}|{n}']['z']:+.1f},3sd{res[f'{comp}|{s}|{n}']['A_3sigma_detectable_nT']},pw{res[f'{comp}|{s}|{n}']['power_minus17_at_3sigma']})" for n in ['obsc_tau0','obsc_tau30','obsc_tau60','c14_local','c14_global']))
json.dump(res,open('zfit.json','w'),indent=1)

