import glob,re
def hdr(s):
    f=sorted(glob.glob(f'day/{s}_2026-08-12.txt'))+[f'{s}.txt']
    for fn in f:
        try:
            lat=lon=None
            for l in open(fn):
                if 'Geodetic Latitude' in l: lat=float(l.split()[2])
                if 'Geodetic Longitude' in l: lon=float(l.split()[2]); lon=lon-360 if lon>180 else lon
                if l.startswith('DATE'): break
            if lat is not None: return lat,lon
        except FileNotFoundError: pass
